---@param v any
---@return string
local function text(v) return v ~= nil and tostring(v) or "" end

---@param v any
---@return string[]
local function strings(v)
  local out = {}
  if type(v) ~= "table" then return out end
  for i = 1, #v do out[i] = tostring(v[i]) end
  return out
end

---@param raw table
---@return fx.Deferrals deferrals
---@return fun(): boolean pending Deferred and not done yet
local function trackDeferrals(raw)
  local deferred, finished = false, false
  ---@type fx.Deferrals
  local d = {
    defer = function() deferred = true; raw.defer() end,
    ---@param message string
    update = function(message) raw.update(message) end,
    ---@param card string|table<string, any>
    ---@param cb? fun(data: table<string, any>, rawData: string)
    presentCard = function(card, cb) raw.presentCard(card, cb) end,
    ---@param failureReason? string
    done = function(failureReason)
      finished = true
      raw.done(failureReason)
    end,
    ---@param data table<string, any>
    handover = function(data) raw.handover(data) end,
  }
  return d, function() return deferred and not finished end
end

