---@param fn fun(connection: fx.PlayerConnection)
---@return fun() off
Cfx.onPlayerConnecting = function(fn)
  K.checkFn("Cfx.onPlayerConnecting", fn)
  ---@param name string
  ---@param setKickReason fun(reason: string)
  ---@param raw table
  return K.listen("playerConnecting", function(name, setKickReason, raw)
    local src = K.int(source) or 0
    local deferrals, pending = trackDeferrals(raw)
    local ok = K.call("Cfx.onPlayerConnecting", fn, {
      source = src, name = text(name), player = K.player(src), deferrals = deferrals,
      setKickReason = setKickReason, cancel = CancelEvent,
    })
    -- a deferred connection left open keeps the player on the loading screen forever
    if not ok and pending() then deferrals.done("The server could not check your connection.") end
  end)
end

