local Game = {}

-- OneSync routed game events: (sender, data), sender is the server id as a string. Returning after CancelEvent()
-- keeps the event from reaching its target clients (NetGameEventPacketHandler.cpp).
---@param label string
---@param event string
---@param decode fun(d: table<string, any>): table<string, any>?
---@return fun(fn: fun(e: table)): fun()
local function netEvent(label, event, decode)
  return function(fn)
    K.checkFn(label, fn)
    ---@param sender any
    ---@param data any
    return K.listen(event, function(sender, data)
      local raw = K.tbl(data)
      local ok, e = pcall(decode, raw)
      if not ok then return K.logError(label, e) end
      if not e then return end
      e.sender, e.data, e.cancel = K.player(sender), raw, CancelEvent
      K.call(label, fn, e)
    end)
  end
end

-- the GTA V game events FiveM routes through the server (ServerGameState.cpp)
---@type fx.GameRoutedEventName[]
local ROUTED = {
  "weaponDamageEvent", "weaponDamageReply", "explosionEvent", "fireEvent", "startProjectileEvent", "ptFxEvent",
  "giveWeaponEvent", "removeWeaponEvent", "removeAllWeaponsEvent", "clearPedTasksEvent", "givePedScriptedTaskEvent",
  "vehicleComponentControlEvent", "vehicleComponentControlReply", "respawnPlayerPedEvent", "respawnPlayerPedReply",
  "requestNetworkSyncedSceneEvent", "startNetworkSyncedSceneEvent", "updateNetworkSyncedSceneEvent",
  "stopNetworkSyncedSceneEvent",
}

---@param label string
---@param name string
---@param fn fun(e: fx.GameEvent.Raw)
---@return fun() off
local function onRaw(label, name, fn)
  ---@param sender any
  ---@param data any
  return K.listen(name, function(sender, data)
    K.call(label, fn, { name = name, sender = K.player(sender), data = K.tbl(data), cancel = CancelEvent })
  end)
end

---@param name string
---@param fn fun(e: fx.GameEvent.Raw)
---@return fun() off
Game.on = function(name, fn)
  if type(name) ~= "string" or name == "" then error("fx.Events.Game.on: name must be an event name", 2) end
  K.checkFn("Game.on", fn)
  return onRaw("Game.on", name, fn)
end

---@param fn fun(e: fx.GameEvent.Raw)
---@return fun() off
Game.onAny = function(fn)
  K.checkFn("Game.onAny", fn)
  ---@type (fun())[]
  local offs = {}
  for i, name in ipairs(ROUTED) do offs[i] = onRaw("Game.onAny", name, fn) end
  return function()
    for _, off in ipairs(offs) do off() end
  end
end

---@param list any
---@return fx.Entity[]
local function entitiesOfNetIds(list)
  local out = {}
  for _, id in ipairs(K.tbl(list)) do
    local e = K.entityOfNetId(id)
    if e then out[#out + 1] = e end
  end
  return out
end

Game.onWeaponDamage = netEvent("Game.onWeaponDamage", "weaponDamageEvent", function(d)
  local damageType = K.int(d.damageType) or 0
  local hasVehicleData = d.hasVehicleData == true
  return {
    victim = K.entityOfNetId(d.hitGlobalId),
    victims = entitiesOfNetIds(d.hitGlobalIds),
    weapon = K.hash(d.weaponType),
    damageType = damageType,
    damage = d.overrideDefaultDamage == true and (K.int(d.weaponDamage) or 0) or nil,
    damageFlags = K.int(d.damageFlags) or 0,
    silenced = d.silenced == true,
    willKill = damageType == 3 and d.willKill == true,
    component = damageType >= 2 and K.int(d.hitComponent) or nil,
    tyreIndex = hasVehicleData and K.int(d.tyreIndex) or nil,
    suspensionIndex = hasVehicleData and K.int(d.suspensionIndex) or nil,
    localPosition = d.isNetTargetPos == true and K.vec(d.localPosX, d.localPosY, d.localPosZ) or nil,
    impactDirection = d.hasImpactDir == true and K.vec(d.impactDirX, d.impactDirY, d.impactDirZ) or nil,
  }
end)

Game.onExplosion = netEvent("Game.onExplosion", "explosionEvent", function(d)
