    explosionType = K.int(d.explosionType) or 0,
    position = K.vec(d.posX, d.posY, d.posZ),
    damageScale = tonumber(d.damageScale) or 0.0,
    cameraShake = tonumber(d.cameraShake) or 0.0,
    audible = d.isAudible == true,
    invisible = d.isInvisible == true,
  }
end)

Game.onFire = netEvent("Game.onFire", "fireEvent", function(d)
  -- CFireEvent is packed with MSGPACK_DEFINE (an array): the fires are its first element
  local list = d.fires or d[1]
  local fires = {}
  for _, f in ipairs(K.tbl(list)) do
    f = K.tbl(f)
    fires[#fires + 1] = {
      entity = f.isEntity == true and K.entityOfNetId(f.entityGlobalId) or nil,
      position = K.vec(f.posX, f.posY, f.posZ),
      maxChildren = K.int(f.maxChildren) or 0,
      weapon = K.hash(f.weaponHash),
      fireId = K.int(f.fireId) or 0,
    }
  end
  return { fires = fires }
end)

