---@type table<string, "request"|"start"|"update"|"stop">
local SCENE_ACTIONS = {
  requestNetworkSyncedSceneEvent = "request", startNetworkSyncedSceneEvent = "start",
  updateNetworkSyncedSceneEvent = "update", stopNetworkSyncedSceneEvent = "stop",
}

---@param fn fun(e: fx.GameEvent.SyncedScene)
---@return fun() off
Game.onSyncedScene = function(fn)
  K.checkFn("Game.onSyncedScene", fn)
  ---@type (fun())[]
  local offs = {}
  for event, action in pairs(SCENE_ACTIONS) do
    offs[#offs + 1] = netEvent("Game.onSyncedScene", event, function(d)
      local start = action == "start"
      return {
        action = action,
        sceneId = K.int(d.sceneId) or 0,
        rate = (action == "update" or start) and (tonumber(d.rate) or 1.0) or nil,
        position = start and K.vec(d.scenePosX, d.scenePosY, d.scenePosZ) or nil,
        attachedTo = start and d.hasAttachEntity == true and K.entityOfNetId(d.attachEntityId) or nil,
        looped = start and d.isLooped == true or nil,
      }
    end)(fn)
  end
  return function()
    for _, off in ipairs(offs) do off() end
  end
end

