---@param fn fun(players: fx.Player[], netIds: integer[])
---@return fun() off
Tx.onAdminsUpdated = function(fn)
  K.checkFn("TxAdmin.onAdminsUpdated", fn)
  ---@param ids any
  return K.listen("txAdmin:events:adminsUpdated", function(ids)
    local netIds, players = {}, {}
    for _, v in ipairs(K.tbl(ids)) do
      local id = K.int(v)
      if id then
        netIds[#netIds + 1] = id
        local p = K.player(id)
        if p then players[#players + 1] = p end
      end
    end
    K.call("TxAdmin.onAdminsUpdated", fn, players, netIds)
  end)
end

